css.value:
* {
    color: var(--now-color_text--primary);

    /* Display type/header hero */
    font-family: var(--Typography-Font---now-heading--font-family, Cabin);
    font-size: var(--Typography-Size-Display-header-hero, 32px);
    font-style: normal;
    font-weight: 700;
    line-height: normal;
}

* {
    color: var(--now-color_text--secondary);
    font-feature-settings: 'liga'off, 'clig'off;

    /* Text/md */
    font-family: var(--Typography-Font---now-font-family, Lato);
    font-size: var(--Typography-Size-Text-text-md, 16px);
    font-style: normal;
    font-weight: 400;
    line-height: normal;
}

