font-size: var(--Typography-Size-Text-text-sm, 12px);
font-style: normal;
font-weight: 400;
line-height: normal;
}

script.inlineScript:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    var selectedItem = event.payload.item.id;
    var trendFreq = (selectedItem == "monthly") ? "MONTH" : "WEEK";

    return {
        propName: "trendFrequency",
        value: trendFreq
    };
}

